#include <vector>

class Solution {
public:
    std::vector<int> findMissingAndRepeatedValues(std::vector<std::vector<int>>& grid) {
        int n = grid.size();
        int total = n * n;
        std::vector<int> count(total + 1, 0);
        for (const auto& row : grid) {
            for (int val : row) {
                count[val]++;
            }
        }
        int repeated = -1, missing = -1;
        for (int x = 1; x <= total; ++x) {
            if (count[x] == 2) repeated = x;
            else if (count[x] == 0) missing = x;
        }
        return {repeated, missing};
    }
};

class Solution {
    public int[] findMissingAndRepeatedValues(int[][] grid) {
        int n = grid.length;
        int total = n * n;
        int[] count = new int[total + 1];
        for (int[] row : grid) {
            for (int val : row) {
                count[val]++;
            }
        }
        int repeated = -1, missing = -1;
        for (int x = 1; x <= total; x++) {
            if (count[x] == 2) repeated = x;
            else if (count[x] == 0) missing = x;
        }
        return new int[]{repeated, missing};
    }
}

var findMissingAndRepeatedValues = function(grid) {
    const n = grid.length;
    const total = n * n;
    const count = new Array(total + 1).fill(0);
    for (const row of grid) {
        for (const val of row) {
            count[val]++;
        }
    }
    let repeated = -1, missing = -1;
    for (let x = 1; x <= total; x++) {
        if (count[x] === 2) repeated = x;
        else if (count[x] === 0) missing = x;
    }
    return [repeated, missing];
};
